package models

import (
	cesium "github.com/fullstack-lang/gong/lib/cesium/go/models"
	maplibre "github.com/fullstack-lang/gong/lib/maplibre/go/models"
)

func (stager *Stager) ux_cesium() {
	if stager.cesiumStage == nil || stager.maplibreStage == nil {
		return
	}

	stager.cesiumStage.Reset()

	mlViews := stager.maplibreStage.GetInstancesSorted[*maplibre.MapView]()
	if len(mlViews) == 0 {
		stager.cesiumStage.Commit()
		return
	}
	mlView := mlViews[0]

	pitch := mlView.Pitch
	if pitch < 45.0 {
		pitch = 48.0
	}

	cesiumView := &cesium.MapView{
		Name:      "AIXM 3D Aeronautical Globe",
		StyleURL:  "offline",
		Latitude:  mlView.Latitude,
		Longitude: mlView.Longitude,
		Zoom:      mlView.Zoom,
		Pitch:     pitch,
		Bearing:   mlView.Bearing,
	}

	topAltByLabel := make(map[string]float64)

	for _, mlLayer := range mlView.Layers {
		if mlLayer == nil {
			continue
		}
		cLayer := &cesium.Layer{
			Name:      mlLayer.Name,
			IsVisible: mlLayer.IsVisible,
		}

		for _, mlPoly := range mlLayer.Polygons {
			if mlPoly == nil {
				continue
			}
			mlPoly := mlPoly
			baseAlt := mlPoly.BaseAltitude
			topAlt := mlPoly.ExtrusionHeight
			extrudeHeight := topAlt - baseAlt
			if extrudeHeight < 150 {
				extrudeHeight = 350
			}
			actualTop := baseAlt + extrudeHeight
			if mlPoly.Label != "" && actualTop > topAltByLabel[mlPoly.Label] {
				topAltByLabel[mlPoly.Label] = actualTop
			}

			cPoly := &cesium.Polygon{
				Name:            mlPoly.Name,
				Label:           mlPoly.Label,
				PopupHTML:       mlPoly.PopupHTML,
				FillColor:       mlPoly.FillColor,
				FillOpacity:     mlPoly.FillOpacity,
				StrokeColor:     mlPoly.StrokeColor,
				StrokeOpacity:   mlPoly.StrokeOpacity,
				StrokeWidth:     mlPoly.StrokeWidth,
				IsExtruded:      true,
				BaseAltitude:    baseAlt,
				ExtrusionHeight: extrudeHeight,
			}
			if mlPoly.OnClick != nil {
				cPoly.OnClick = func(_ *cesium.Polygon) {
					mlPoly.OnClick(mlPoly)
				}
			}
			for _, coord := range mlPoly.Coordinates {
				if coord == nil {
					continue
				}
				cPoly.Coordinates = append(cPoly.Coordinates, &cesium.Coordinate{
					Name:      coord.Name,
					Latitude:  coord.Latitude,
					Longitude: coord.Longitude,
					Altitude:  baseAlt,
				})
			}
			cLayer.Polygons = append(cLayer.Polygons, cPoly)
		}

		for _, mlLine := range mlLayer.Polylines {
			if mlLine == nil {
				continue
			}
			mlLine := mlLine
			lineAlt := 120.0
			if mlLine.Label != "" && topAltByLabel[mlLine.Label] > 0 {
				lineAlt = topAltByLabel[mlLine.Label] + 20
			}
			cLine := &cesium.Polyline{
				Name:            mlLine.Name,
				Label:           mlLine.Label,
				PopupHTML:       mlLine.PopupHTML,
				StrokeColor:     mlLine.StrokeColor,
				StrokeOpacity:   mlLine.StrokeOpacity,
				StrokeWidth:     mlLine.StrokeWidth,
				StrokeDashArray: mlLine.StrokeDashArray,
			}
			if mlLine.OnClick != nil {
				cLine.OnClick = func(_ *cesium.Polyline) {
					mlLine.OnClick(mlLine)
				}
			}
			for _, coord := range mlLine.Coordinates {
				if coord == nil {
					continue
				}
				cLine.Coordinates = append(cLine.Coordinates, &cesium.Coordinate{
					Name:      coord.Name,
					Latitude:  coord.Latitude,
					Longitude: coord.Longitude,
					Altitude:  lineAlt,
				})
			}
			cLayer.Polylines = append(cLayer.Polylines, cLine)
		}

		for _, mlMarker := range mlLayer.Markers {
			if mlMarker == nil {
				continue
			}
			mlMarker := mlMarker
			markerAlt := mlMarker.Altitude
			if markerAlt <= 0 {
				if top := topAltByLabel[mlMarker.Label]; top > 0 {
					markerAlt = top + 120
				} else {
					markerAlt = 200
				}
			}
			cMarker := &cesium.Marker{
				Name:              mlMarker.Name,
				Label:             mlMarker.Label,
				PopupHTML:         mlMarker.PopupHTML,
				Longitude:         mlMarker.Longitude,
				Latitude:          mlMarker.Latitude,
				Altitude:          markerAlt,
				SVG:               mlMarker.SVG,
				Color:             mlMarker.Color,
				Scale:             mlMarker.Scale,
				Rotation:          mlMarker.Rotation,
				RotationAlignment: cesium.MarkerPitchAlignmentEnum(mlMarker.RotationAlignment),
				PitchAlignment:    cesium.MarkerPitchAlignmentEnum(mlMarker.PitchAlignment),
				Anchor:            cesium.MarkerAnchorEnum(mlMarker.Anchor),
				IsDraggable:       mlMarker.IsDraggable,
			}
			if mlMarker.OnClick != nil {
				cMarker.OnClick = func(_ *cesium.Marker) {
					mlMarker.OnClick(mlMarker)
				}
			}
			cLayer.Markers = append(cLayer.Markers, cMarker)
		}

		cesiumView.Layers = append(cesiumView.Layers, cLayer)
	}

	stager.cesiumStage.StageBranch(cesiumView)
	stager.cesiumStage.Commit()
}
